<script setup>
import { uniqueKey } from '../../services/ids.js';
import { reactive,ref,computed,onMounted } from 'vue';
import { useRoute,useRouter } from 'vue-router';
import { api } from '../../services/api.js';
import { workspace,loadStores } from '../../services/workspace.js';
import { notify } from '../../services/notifications.js';
import Icon from '../../components/Icon.vue';
const route=useRoute(),router=useRouter(),editing=computed(()=>!!route.params.id),loading=ref(true),saving=ref(false),error=ref(''),store=ref(null);let original='';
const form=reactive({id:uniqueKey(),type:'pickup',name:'Retiro en el local',description:'',price:0,active:true});
const types={pickup:'Retiro en el local',shipping:'Envío',digital:'Entrega digital',custom:'Entrega personalizada'};
onMounted(async()=>{try{store.value=await api.get(`/stores/${workspace.activeStoreId}`);if(editing.value){const item=store.value.deliveries.find(d=>d.id===route.params.id);if(!item)throw new Error('La forma de entrega no existe.');original=JSON.stringify(item);Object.assign(form,item);}}catch(e){error.value=e.message}finally{loading.value=false}});
async function save(){saving.value=true;error.value='';try{const latest=await api.get(`/stores/${workspace.activeStoreId}`),index=latest.deliveries.findIndex(d=>d.id===form.id);if(editing.value&&(index<0||JSON.stringify(latest.deliveries[index])!==original))throw new Error('Esta entrega cambió desde que abriste el formulario. Volvé al listado y abrila nuevamente para conservar los cambios más recientes.');if(index>=0)latest.deliveries[index]=JSON.parse(JSON.stringify(form));else latest.deliveries.push(JSON.parse(JSON.stringify(form)));await api.put(`/stores/${workspace.activeStoreId}/payments`,{payments:latest.payments,deliveries:latest.deliveries,expectedUpdatedAt:latest.updatedAt});await loadStores();notify.success('Forma de entrega guardada.');router.push('/app/payments?tab=entregas')}catch(e){error.value=e.message;notify.error(e.message)}finally{saving.value=false}}
</script>
<template><div><RouterLink to="/app/payments?tab=entregas" class="p-back-link"><Icon name="back" :size="14"/>Volver a entregas</RouterLink><header class="p-page-header"><div><h1>{{editing?'Editar forma de entrega':'Nueva forma de entrega'}}</h1><p>Indicá el costo y todo lo que el cliente necesita saber.</p></div></header><div v-if="error" class="p-error">{{error}}</div><div v-if="loading" class="p-loading-page"><span class="p-spinner"/></div><form v-else-if="store" @submit.prevent="save" class="p-form"><section class="p-section-card"><div class="p-section-title"><h2>Datos de la entrega</h2><Icon name="truck"/></div><div class="p-form-grid"><div class="p-field"><label for="delivery-type">Tipo</label><select id="delivery-type" v-model="form.type" @change="form.name=types[form.type]"><option v-for="(label,type) in types" :key="type" :value="type">{{label}}</option></select></div><div class="p-field"><label for="delivery-name">Nombre visible *</label><input id="delivery-name" v-model.trim="form.name" required maxlength="120"/></div><div class="p-field full"><label for="delivery-description">Instrucciones para el cliente</label><textarea id="delivery-description" v-model="form.description" rows="4" maxlength="1000" placeholder="Dirección de retiro, zonas de envío, horarios o tiempos estimados..."/></div><div class="p-field"><label for="delivery-price">Costo (ARS) *</label><input id="delivery-price" v-model.number="form.price" type="number" min="0" step="0.01" required/><small>0 para entrega gratuita.</small></div><div class="p-field"><label class="p-check"><input v-model="form.active" type="checkbox"/>Habilitar esta entrega</label></div></div><div v-if="form.type==='digital'" class="p-info">La entrega digital solo se ofrece cuando todos los productos del carrito son digitales. Los enlaces se enviarán por correo después de confirmar el pago.</div><div v-if="['shipping','custom'].includes(form.type)" class="p-info">El checkout solicitará la dirección del cliente. El costo es fijo: no se consulta una tarifa de correo o transportista.</div></section><footer class="p-form-footer"><small>Después podés asociar medios de pago a esta entrega.</small><div class="p-form-actions"><RouterLink to="/app/payments?tab=entregas" class="btn btn-secondary">Cancelar</RouterLink><button class="btn btn-primary" :disabled="saving">{{saving?'Guardando...':'Guardar entrega'}}</button></div></footer></form></div></template>
